Method.Implementation:

	set tStat = ..CheckSvnSetup(usrNm, passwd)

	 IF $$$ISERR( tStat )
	 {
		  	set tExp = ##class(%Exception.General).%New()
		  	set tExp.Name = "Setup error: " _ tStat.Data
		  	set tExp.Code=999
		  	set tExp.Location = "CheckSvnSetup"
		  	set tExp.Data = "Check: " _ $$$USRBASEDIR _ usrNm
		  	Throw tExp
	 }

	 NEW $NAMESPACE
    SET $NAMESPACE = "ITFCOMMON"

	// All files for ITFCOMMON namespace will be under IHC
	set numFiles = 0
	set lastSvnDtTm = ..GetSVNLastUpdateTime()
	set lastSvnIntTm = $ZDATETIMEH(lastSvnDtTm, 3, 1)

	set stDtTm = $ZDATETIME($HOROLOG,3, 1)
	set tempFile = $$$USRBASEDIR _ usrNm _ "/tempSvnList"
	set svnTempFile = $$$USRBASEDIR _ usrNm _ "/tempSvnFull"
	set fileInfo = ""

 	set fullPath =  $$$USRBASEDIR _ usrNm _  $$$SVNSRCTRUNK 

 	Set cmd = $$$SVNUPDATEALL _ " --username " _ usrNm _ " --password '" _ passwd _ "' " _ fullPath 
    Set stat = ##class(IHC.ITF.SrcCtrlPkg.EnsembleSrcCtrlClass).ExecuteShellCmd( cmd)
    Do ##class(IHC.ITF.ITFCOMMON.Utility).WriteToFile("CreateListOfFilesInSvn: " _ $$$SVNUPDATEALL _ " for " _ fullPath _": "_stat)

    Set cmd = $$$SVNINFO _ " -R --username " _ usrNm _ " --password '" _ passwd  _ "' " _ fullPath _ " > " _ svnTempFile
	Set stat = ##class(IHC.ITF.SrcCtrlPkg.EnsembleSrcCtrlClass).ExecuteShellCmd( cmd)

	Do ##class(IHC.ITF.ITFCOMMON.Utility).WriteToFile( $$$SVNINFO _ "for " _ fullPath _" : " _ stat)

	If ( ##class(%File).Exists(svnTempFile) = 0)
	{
		Do ##class(IHC.ITF.ITFCOMMON.Utility).WriteToFile( "Did not create file from : " _ $$$SVNINFO)
		Quit
	}
	else
	{
		Set cmd = "grep -E "" URL|Kind|Last Changed "" " _ svnTempFile _ " > " _ tempFile
		Set stat = ##class(IHC.ITF.SrcCtrlPkg.EnsembleSrcCtrlClass).ExecuteShellCmd( cmd)

		Do ##class(IHC.ITF.ITFCOMMON.Utility).WriteToFile( cmd _", stat : " _ stat)

	}
	If ( ##class(%File).Exists(tempFile) = 0)
	{
		Do ##class(IHC.ITF.ITFCOMMON.Utility).WriteToFile( "Did not create file from grep")
		Quit
	}
	Do ##class(IHC.ITF.ITFCOMMON.Utility).WriteToFile("Update files checkedin to SubVersion after: " _ lastSvnDtTm _ " Internal time: "_ lastSvnIntTm)
	Set fileObj=##class(%Library.File).%New(tempFile)
         set fileOpen = fileObj.Open("RS") ; Read mode and as stream
        set int = 1
        set isFile = 0
         While 'fileObj.AtEnd 
         {
	         set readStr = fileObj.ReadLine(1000, .sc, .stat)
	         if ($L(readStr) > 0)
	         {
		         if (readStr [ "URL:")
		         {
			         set file = $E(readStr, $F(readStr, $ZSTRIP($$$SVNSRCURL, "*W") _ "/"), *)

		         }
		         elseif(readStr [ "Node Kind: file")
		         {		         
			         set int = int + 1
			         set isFile = 1
		         }
		         elseif(readStr [ "Rev: ")
		         {
			         set rev = $E(readStr,  $F(readStr , "Rev: "), *)
		         }
		         elseif(readStr [ "Author: ")
		         {
			         set author = $E(readStr,  $F(readStr , "Author: "), *)
		         }
		         elseif(readStr [   "Date: ")
		         {
			         if (isFile = 1)
			         {
			       		set fileStamp = $E(readStr,  $F(readStr , "Date: "), $F(readStr , " -") -3)
			       		set flIntTm = $ZDATETIMEH(fileStamp, 3, 1)

			       		if ( ($PIECE(flIntTm, ",") > $PIECE(lastSvnIntTm, ","))
						|| ( ($PIECE(lastSvnIntTm, ",") = $PIECE(flIntTm, ",") ) 
						&& ($PIECE(flIntTm, ",", 2) > $PIECE(lastSvnIntTm, ",", 2)) )
						)
						{
			       			set isFile = 0
			       			set updStr = rev
			       			set oper = "UPDATE"
			       			&sql(UPDATE  IHC_ITF_SrcCtrlPkg.ClassInfo 
			       			SET FileModifiedTime=:fileStamp, VersionNumber = :updStr, CheckinUser = :author 
			       			WHERE FileName=:file )
			       			if SQLCODE '= 0 {
				     	  		set oper = "INSERT"
	       						&sql(INSERT INTO IHC_ITF_SrcCtrlPkg.ClassInfo 
	       						(FileName, FileModifiedTime, VersionNumber, CheckinUser) 
	       							VALUES (:file, :fileStamp, :updStr, :author))
        					}
        					Do ##class(IHC.ITF.ITFCOMMON.Utility).WriteToFile( int _ ". " _ oper _ " - " _ file _ ", " _ rev _ ", " _ fileStamp _ ", internal time: " _ flIntTm _ ", SQLCODE: " _ SQLCODE)
        					set numFiles = numFiles + 1
			         	}
			         }
		         }

	         }	       
         }
         Do fileObj.Close()
         set endDtTm = $ZDATETIME($HOROLOG,3, 1)
         Do ..UpdateProcessTime("SVN update", stDtTm, endDtTm)
         Do ##class(IHC.ITF.ITFCOMMON.Utility).WriteToFile("CreateListOfFilesInSvn: Updated SVN information for " _ numFiles _ " files.")
         Return numFiles

  NEW $NAMESPACE
  set $NAMESPACE = "ITFCOMMON"
  set prevEnsDt = ..GetEnsembleLastUpdateTime()

  set prevDt = $PIECE($ZDATETIMEH(prevEnsDt, 3, 1), ",") -1
  set nowDt = $PIECE($H, ",")
  Do ##class(IHC.ITF.ITFCOMMON.Utility).WriteToFile("UpdateClassesFromAudit: Start " _ $username _ ", last update: " _ prevEnsDt)
  set stDtTm = $ZDATETIME($HOROLOG,3, 1)
 try {

  while (prevDt <= nowDt)
  {

	set BeginDateTime =  $PIECE($zdatetime(prevDt,3)," ")  _ "%"
  	set $NAMESPACE = "ITFCOMMON"
  	Do ##class(IHC.ITF.ITFCOMMON.Utility).WriteToFile("Get audit entries for " _ $username _ ", for: " _ BeginDateTime _" from: " _ prevDt _ " till: " _ nowDt)

    set prevDt = prevDt +1
    set $NAMESPACE ="%SYS"


    &sql(DECLARE C1 CURSOR FOR
     Select AuditIndex, Username, Namespace, Event, Description,  UTCTimeStamp
    	Into :ind, :usrNm, :nmSp, :evt, :desc, :utcTm 
		From %SYS.Audit  
		Where Event in ( 'ROUTINECHANGE', 'MODIFY', 'CHANGE')
		and Status = 1
		 and UTCTimeStamp like :BeginDateTime
		 order by Description, AuditIndex)

  &sql(OPEN C1)
  &sql(FETCH C1)
  set prevNm = "ZZZZZ"
  set prevUsrNm = "ZZZZZ"
  set locTm = "ZZZZZ"
  set prevNmSp = "ZZZZZ"
  set intNm = ""


  WHILE (SQLCODE = 0) {
     set pos = $FIND($REVERSE(desc),$REVERSE(".cls"))
     if (pos <= 0)
     {
	     set pos = $FIND($REVERSE(desc),$REVERSE(".CLS"))
     }

     if ( (desc [ "IHC") && (pos = 5) && ('(desc [ "Thread1.cls"))  && ('(desc [ "Context.cls")) )
     {
     	set intNm = $P(desc, "|", 3)
     	set notF = 0
     }
     elseif ( $F(desc, "HL7") = 4)
     {
	     set intNm =  $P(desc, " ", 2) _ "." _ $P(desc, " ", 1)
	     set notF = 0
     }
     elseif ( (desc [ "DStruc") && (desc [ "Context.cls") )
     {
	     set intNm = $P(desc, "|", 3)
	     set notF = 0
     }
     else
     {
	     set notF = 1
     }

     if (notF = 0)
     {
     	if ( (intNm '= "") && (prevNm  '= "") && (prevNm '= intNm) || (prevNmSp '= nmSp) ) {

	  	 	set $NAMESPACE ="ITFCOMMON"
        	Do ..UpdateClassInformationInTable(prevNm , prevNmSp , locTm , prevUsrNm )
        	set $NAMESPACE = "%SYS"

			s locTm =##Class(%SYS.Audit).ConvertUTCToLocal(utcTm)
			set prevUsrNm = usrNm
			set prevNmSp = nmSp
			set prevNm = intNm
    	}
    	elseif (intNm '= "")
    	{
	    	s locTm =##Class(%SYS.Audit).ConvertUTCToLocal(utcTm)
	    	set prevUsrNm = usrNm
	    	set prevNmSp = nmSp
	    	set prevNm = intNm
	    	// WRITE !, intNm _ ". " _ locTm

     	}
     }


     &sql(FETCH C1) 
    }
    &sql(CLOSE C1)

    if (prevNm '= "ZZZZZ")
    {
		Do ..UpdateClassInformationInTable(prevNm , prevNmSp , locTm , prevUsrNm ) 
    }

  }
    set endDtTm = $ZDATETIME($HOROLOG,3, 1)
    Do ..UpdateProcessTime("Ensemble update", stDtTm, endDtTm)
    SET $NAMESPACE = "ITFCOMMON"
    Do ##class(IHC.ITF.ITFCOMMON.Utility).WriteToFile("UpdateClassesFromAudit: Complete " _ $username _ ", update time: " _ endDtTm)

 } catch err
 {
	 SET $NAMESPACE = "ITFCOMMON"
	 Do ##class(IHC.ITF.ITFCOMMON.Utility).WriteToFile( "Exception: " _ err.Data _", " _ err.Location _ ", " _ err.Name)
 }

	  	 NEW $NAMESPACE
	  	 set $NAMESPACE ="ITFCOMMON"
	  	 set clId = -1
	  	 // Do ##class(IHC.ITF.ITFCOMMON.Utility).WriteToFile( "In UpdateClassInformationInTable: " _ prevIntNm)
	  	 if ( (prevIntNm '= "") && (prevIntNm '= "ZZZZZ") )
		 {
	  	 	Set flNm = ..RelativeFileName(prevIntNm)
		 	set upIntNm = $ZCONVERT(prevIntNm, "U")	

	     	&sql(select  ID into :clId from IHC_ITF_SrcCtrlPkg.ClassInfo  
   	        	WHERE Namespace = :prevNmSp AND (UPPER(InternalName) = :upIntNm  OR FileName = :flNm))

			if SQLCODE '= 0 {
			// Write !, "Not found: " _ nm		
			    &sql(select  ID into :clId from IHC_ITF_SrcCtrlPkg.ClassInfo  
   	        	  WHERE Namespace is NULL AND (UPPER(InternalName) = :upIntNm  OR FileName = :flNm))
   	        	if SQLCODE '= 0 {	
  				   &sql(INSERT INTO IHC_ITF_SrcCtrlPkg.ClassInfo (InternalName, FileName, Namespace, ClassModifiedTime, CompileUser)
					  values (:prevIntNm, :flNm, :prevNmSp, :locTm, :prevUsrNm))
				   Do ##class(IHC.ITF.ITFCOMMON.Utility).WriteToFile( "Insert class: " _ prevIntNm _ ", File name: " _ flNm _ " : " _ locTm _ " : " _ prevUsrNm _ ", SQLCODE: " _ SQLCODE	)
   	        	}
   	        	else
   	        	{
					&sql(UPDATE IHC_ITF_SrcCtrlPkg.ClassInfo SET InternalName = :prevIntNm, FileName = :flNm, 
					Namespace = :prevNmSp, ClassModifiedTime = :locTm, CompileUser = :prevUsrNm
					where Namespace is NULL AND (UPPER(InternalName) = :upIntNm  OR FileName = :flNm))

					Do ##class(IHC.ITF.ITFCOMMON.Utility).WriteToFile( "Update class: " _ prevIntNm _ ", File name: " _ flNm _ " : " _ locTm _ " : " _ prevUsrNm _  ", Namespace was Null, SQLCODE: " _ SQLCODE	 	)	

   	        	}
			}
			else
			{				
					&sql(UPDATE IHC_ITF_SrcCtrlPkg.ClassInfo SET InternalName = :prevIntNm, FileName = :flNm, 
					Namespace = :prevNmSp, ClassModifiedTime = :locTm, CompileUser = :prevUsrNm
					where Namespace = :prevNmSp AND (UPPER(InternalName) = :upIntNm  OR FileName = :flNm))

					Do ##class(IHC.ITF.ITFCOMMON.Utility).WriteToFile( "Update class: " _ prevIntNm _ ", File name: " _ flNm _ " : " _ locTm _ " : " _ prevUsrNm _ "in namespace: " _ prevNmSp _ ", SQLCODE: " _ SQLCODE	 	)	
			}
	}


	set fileInfo = ""

	Do ##class(IHC.ITF.ITFCOMMON.Utility).WriteToFile("GetSvnInformation " _ $NAMESPACE _ " " _ usrNm _ " " _ Selectedfiles)
	if (Selectedfiles = "")
	{
		Quit $$$ERROR(6484, "FileName")
	}
	For I=1:1:$L(Selectedfiles,",")
	{
		Set fileNm = $P(Selectedfiles,",",I)
		Set fullFileNm = $$$USRBASEDIR _ usrNm _ $$$SVNSRCTRUNK _ fileNm

		set tempFile = 	fullFileNm _ "Temp"
		if (##class(%File).Exists(tempFile) )
	  	{
			Do ##class(%Library.File).Delete(tempFile)
	  	}
		if ( (fileNm '= "") && (##class(%File).Exists(fullFileNm) ) )
		{	 


	         Set cmd= $$$SVNINFO _ fullFileNm _ " >> " _ tempFile

			 Set status = ##class(IHC.ITF.SrcCtrlPkg.EnsembleSrcCtrlClass).ExecuteShellCmd( cmd)

	         Set cmd=  $$$SVNLOG _" --username " _ usrNm _ " --password '" _ passwd _ "' " _ fullFileNm _ " >> " _ tempFile 

			 Set status = ##class(IHC.ITF.SrcCtrlPkg.EnsembleSrcCtrlClass).ExecuteShellCmd( cmd)

	  		if (##class(%File).Exists(tempFile) )
	  		{
         		#; Call the function to do the load
         		Set tStatus=..GetFileContent(tempFile) 
         		Set fileInfo = fileInfo _ tStatus       
	  		}
	  		else
	  		{
		  		SET fileInfo = "svn command failed: " _ cmd
	  		}
		}
		elseif (fileNm '= "")
		{
			SET fileInfo = fileInfo _ " Failed find file: " _ fileNm
		}
	}
	Quit fileInfo


	set fileInfo = ""

	Do ##class(IHC.ITF.ITFCOMMON.Utility).WriteToFile("GetDiff: " _ Selectedfiles)
	if (Selectedfiles = "")
	{
		Quit $$$ERROR(6484, "FileName")
	}
	For I=1:1:$L(Selectedfiles,",")
	{
		Set fileNm = $P(Selectedfiles,",",I)
		set ind = $F(fileNm, $$$SVNSRCTRUNK)
		if ( ind > 0) 
		{
			Set fullFileNm = fileNm
			set fileNm = $E(fullFileNm, ind, *)
		}
		else
		{
			Set fullFileNm = $$$USRBASEDIR _ usrNm _ $$$SVNSRCTRUNK _ fileNm
		}

		set tempFile = 	##class(%Library.File).TempFilename()
		set diffFile = 	fullFileNm _ "Diff"
		if (##class(%File).Exists(tempFile) )
	  	{
			Do ##class(%Library.File).Delete(tempFile)
	  	}
	  	if (##class(%File).Exists(diffFile) )
	  	{
			Do ##class(%Library.File).Delete(diffFile)
	  	}
     if ( (fileNm '= "") && (##class(%File).Exists(fullFileNm) ) )
     {

     set InternalName = ..GetInternalName(fileNm)
	 Do ##class(IHC.ITF.ITFCOMMON.Utility).WriteToFile(fullFileNm _ " = " _ "Int name: " _ InternalName)
	 IF InternalName '= "" 
     { 

	       if ($F(InternalName, ".LOOKUP") > 0)
	        {
		        // Table name is between Namespace - first field and LOOKUP - last field
		        // Example: 
		        // Intername name: RESULTS.IHC.ITF.Process.Bpl.PowerPathReultsHl7To4Medica.Lookup.MedicaLocations.LOOKUP
		        // Table Name: IHC.ITF.Process.Bpl.PowerPathReultsHl7To4Medica.Lookup.MedicaLocations

		        // Strip namespace before first .
		        set tbNm = $E(InternalName, $F(InternalName,"."), *)
		        // String LOOKUP at the end
		        set tbNm = $E(tbNm, 1, ($F(tbNm,"LOOKUP") - 8))

		        Do ##class(IHC.ITF.ITFCOMMON.Utility).WriteToFile("Export lookup table: " _ tbNm _ " to " _ tempFile)

		        Set origNmSp =  $NAMESPACE
	       		Set $NAMESPACE = nmSp
	       		set sc = ##class(Ens.Util.LookupTable).%Export(tempFile, tbNm)
	       		Set $NAMESPACE = origNmSp

	        }
	        else
	        {

     			Set origNmSp =  $NAMESPACE
	        	Set $NAMESPACE = nmSp
	       		Set sc=$$Export^%occXMLExport(tempFile,"-d /diffexport",InternalName)
	       		Set $NAMESPACE = origNmSp
	        }

     }
     if (  ##class(%File).Exists(tempFile)) 
     {
	    Do ##class(IHC.ITF.ITFCOMMON.Utility).WriteToFile( "export file exists: " _ tempFile)
	    set cmd = "diff -w -B --suppress-common-lines " _ tempFile _ " " _ fullFileNm _ " > " _ diffFile
	    Set stat = ##class(IHC.ITF.SrcCtrlPkg.EnsembleSrcCtrlClass).ExecuteShellCmd( cmd)
	    Do ##class(IHC.ITF.ITFCOMMON.Utility).WriteToFile(diffFile)
	    Set diffStr = ..GetFileContent(diffFile) 
	    if (diffStr = "")
	    {
		     set fileInfo = fileInfo  _ "<BR>" _ fileNm _": Files are identical"
	    }
	    else
	    {
		  	 set fileInfo = fileInfo  _ "<BR>" _ fileNm _ "<BR> < Ensemble file <BR> > Source control<BR>" _ diffStr

	    }
	    Do ##class(%Library.File).Delete(tempFile)
	    Do ##class(%Library.File).Delete(diffFile)
     }
	}
	}
	Do ##class(IHC.ITF.ITFCOMMON.Utility).WriteToFile("Diff: " _ fileInfo)
	Quit fileInfo


	set outputStr = "Downloaded files: "

	Do ##class(IHC.ITF.ITFCOMMON.Utility).WriteToFile("DisplayFiles: " _ Selectedfiles _ " " _ usrNm)
	if (Selectedfiles = "")
	{
		Quit $$$ERROR(6484, "FileName")
	}
	For I=1:1:$L(Selectedfiles,",")
	{

	Set fileNm = $P(Selectedfiles,",",I)

     if ( fileNm = "") 
     {
	     continue
     }
     Set fileNm = $$$USRBASEDIR _ usrNm _ $$$SVNSRCTRUNK _ fileNm
     if ( ##class(%File).Exists(fileNm) ) 
     {
	    set newFileNm = $$$USRBASEDIR _ usrNm _ "/" _ ##class(%File).GetFilename(fileNm)
        if ( ##class(%File).CopyFile(fileNm, newFileNm, 1) = 0)
        {
	        set outputStr = "Could not create file: " _ newFileNm
	        Quit
        }
        else
        {
	        set outputStr = outputStr  _ newFileNm _ "; "
        }
     }
     else
     {
	     set outputStr = outputStr  _ "; Could not find file: " _ fileNm
	     Quit
     }
	}

	Quit outputStr


	set tStatus = $$$ERROR(100, "Error in checkout")

	Set origNmSp =  $NAMESPACE
	if (Selectedfiles = "")
	{
		Quit $$$ERROR(6484, "FileName")
	}
	For I=1:1:$L(Selectedfiles,",")
	{
		Set relativeFileNm = $P(Selectedfiles,",",I)
		if ( relativeFileNm '= "")
		{	 
			Set fileNm = $$$USRBASEDIR _ usrNm _ $$$SVNSRCTRUNK _ relativeFileNm
			If ##class(%File).Exists(fileNm)
			{
	  			Do ##class(%File).Delete(fileNm)
	  			 Do ##class(IHC.ITF.ITFCOMMON.Utility).WriteToFile("Delete old version of file: " _ fileNm)
			}	
			if (rev '= "")
			{
				Set cmd= $$$SVNUPDATE _ " --revision " _ rev
			}
			else
			{		
			  Set cmd= $$$SVNUPDATE 
			}
			Set cmd= cmd _ " --username " _ usrNm _ " --password '" _ passwd _ "' " _  fileNm 

			Set status = ##class(IHC.ITF.SrcCtrlPkg.EnsembleSrcCtrlClass).ExecuteShellCmd( cmd)
			If ##class(%File).Exists(fileNm)
			{
				Do ##class(IHC.ITF.ITFCOMMON.Utility).WriteToFile("File Exists after " _ $$$SVNUPDATE _ ", " _ fileNm _ ", status: " _ status)

				NEW $NAMESPACE
	           	Set $NAMESPACE = nmSp


				if ($F(fileNm, "/lookupTables/") > 0)
	        	{
		        	set intNm = ..GetInternalName(relativeFileNm)
		        	if ($LENGTH(intNm) > 0)
		        	{
		        		// Remove Namespace in front and LOOKUP at the end of the name
		        		set tbNm = $EXTRACT(intNm, $FIND(intNm, "."), ($F(intNm,"LOOKUP") - 8))

		        		Do ##class(IHC.ITF.ITFCOMMON.Utility).WriteToFile($NAMESPACE _ " LookupTable name: " _ tbNm)
		        		if ($$$ISOK( ##class(Ens.Util.LookupTable).%ExistsTable(tbNm)))
		        		{
			        		Do ##class(IHC.ITF.ITFCOMMON.Utility).WriteToFile($NAMESPACE _ " Clear the table")
		        			Do ##class(Ens.Util.LookupTable).%ClearTable(tbNm)

		        		}
		        	}
		        	set tStatus = ##class(Ens.Util.LookupTable).%Import(fileNm, "", .cnt)
		        	Do ##class(IHC.ITF.ITFCOMMON.Utility).WriteToFile($NAMESPACE _ " LookupTable Import " _ fileNm _ ", stat: " _ tStatus _ ", entries: " _ cnt)
	        	}
	        	 elseif ($F(fileNm, "systemDefaults/") > 0)
	        	{
		        	set pc = 0
    				set tStatus = ##class(Ens.Config.DefaultSettings).%Import(fileNm, .pc)
    				Do ##class(IHC.ITF.ITFCOMMON.Utility).WriteToFile($NAMESPACE _ " DefaultSettings Import System defaults stat: " _ tStatus _ ", # " _ pc)
	        	}
	        	elseif ($F(fileNm, "tasks/") > 0)
	        	{
   				    set tStatus = ##class(%SYS.Task).ImportTasks(fileNm)
    				Do ##class(IHC.ITF.ITFCOMMON.Utility).WriteToFile(" ImportTasks stat: " _ tStatus _ ", file " _ fileNm)
	        	}
	        	else
	        	{	  
	        		set oldID = $IO
					// Compile line generates output to console; causes javascript to throw error
					OPEN "/dev/null/" 
					USE "/dev/null/"

         	   		#; Call the function to do the load        	   		
         	   		Set tStatus=$system.OBJ.Load(fileNm,"ldck")  
         	   		CLOSE "/dev/null/"

 					OPEN oldID
 					USE oldID 
 					Do ##class(IHC.ITF.ITFCOMMON.Utility).WriteToFile("system.OBJ.Load status: " _ $case(tStatus, 1:" OK",:"Error") )

	        	}

         	   if $$$ISOK(tStatus)
         	   { 
         		 Do ##class(IHC.ITF.ITFCOMMON.Utility).WriteToFile($NAMESPACE _ " File Loaded: " _ fileNm _ ": " _ tStatus)
         		 set intNm = ..GetInternalName(relativeFileNm)
         		 if (intNm = "")
         		 {
	         		 // when a new file is loaded, get the internal name by getting all classes

         		     Do ..UpdateClassesFromAudit()

         			 set intNm = ..GetInternalName(relativeFileNm)
         		 	if (intNm = "")
         			{
	         			  Do ##class(IHC.ITF.ITFCOMMON.Utility).WriteToFile($NAMESPACE _ "Can't get internal name for " _fileNm)
         		 	}
         		 }
         		 set tStatus = $$$OK       
	  		   }
	  		   else
	  		   {
		  		   Do ##class(IHC.ITF.ITFCOMMON.Utility).WriteToFile($NAMESPACE _ " _ File load failed: " _ fileNm)
	  		   }
	  		  if (recMap)
	        	{
		        	// check last part of the file name
		        	if ( $F(relativeFileNm, "Record.xml") = ($LENGTH(relativeFileNm) + 1) )
		        	{
			        	set tStatus = $$$ERROR(100, relativeFileNm _ " should not be checked out, Use it's RecordMap class")
		        	}
		        	else {

			        	// Get class name from file name: replace / with .
			        	// remove cls. from start and .xml from end
			        	set intNm = $REPLACE(relativeFileNm,"/", ".")

 						if ( $F($ZCVT(intNm, "U"), "CLS.") = 5)
 						{
    						set recCls = $EXTRACT(intNm, 5, ($F($ZCVT(intNm, "U"), "XML") - 5))
    						Do ##class(IHC.ITF.ITFCOMMON.Utility).WriteToFile( "CLASS name: " _ recCls)

			        		Set tStatus = ##class(EnsLib.RecordMap.Generator).GenerateObject(recCls,,1,,2,0,"ck",0,.tGenList,0)
							If $$$ISERR(tStatus) {
	    						Do ##class(IHC.ITF.ITFCOMMON.Utility).WriteToFile("GenerateObject " _ $System.Status.GetErrorText( tStatus))

    						}
							// Get all generated classes
							Set tClass = ""
							For {
								Set tClass = $order(tGenList(tClass))
								Quit:(tClass = "")
								Do ##class(IHC.ITF.ITFCOMMON.Utility).WriteToFile( "Generated Class: " _ tClass)
							}


		        			if (##class(EnsLib.RecordMap.RecordMap).Exists(recCls))
		        			{
			        			Do ##class(IHC.ITF.ITFCOMMON.Utility).WriteToFile( "RecordMap: " _ recCls _ ": created")
		        			}
		        			else
		        			{
    					 		Do ##class(IHC.ITF.ITFCOMMON.Utility).WriteToFile( " Could not generate EnsLib.RecordMap.Generator " _ recCls _ ", filename: "_ relativeFileNm)
    					 		set tStatus = $$$ERROR(100, "Class name " _  " Could not generate EnsLib.RecordMap.Generator " _ recCls _ ", filename: "_ relativeFileNm)
		        	   		}
 						}

			        	else
		        		{
    					 Do ##class(IHC.ITF.ITFCOMMON.Utility).WriteToFile("Class name " _ intNm _ " Could not generate valid class name for " _ relativeFileNm)
    					 set tStatus = $$$ERROR(100, "Class name " _ intNm _ " Could not generate valid class name for " _ relativeFileNm)
		        	   }
		        	}
	        	}
	           Set $NAMESPACE = origNmSp
			}
			else
			{
				Do ##class(IHC.ITF.ITFCOMMON.Utility).WriteToFile( $$$SVNUPDATE _ " failed: " _ fileNm)
				set tStatus = $$$ERROR(100, "Error in checked from subversion")
			}
		}
   }
   Do ..UpdateClassesFromAudit()
   Quit tStatus

	// Set usrNm = $username
	set files = ""
	set SelectedIntfiles = ""

	if ( (Selectedfiles = "") || (comment = "") )
	{
		Quit $$$ERROR($$$EnsErrGeneral, "FileNames and comment are empty")
	}
	For I=1:1:$L(Selectedfiles,",")
	{
		Set relativeFileNm = $P(Selectedfiles,",",I)
		Set fileNm = $$$USRBASEDIR _ usrNm _ $$$SVNSRCTRUNK _ relativeFileNm

		if ( relativeFileNm '= "")
		{
		   SET files = files _ " " _ fileNm 
	    }
	    else
	    {
		    continue
	    }

	    Do ..AddDirectoriesToSvn(fileNm, usrNm, passwd)

        // Get latest from Ensemble DB 

	    set InternalName = ..GetInternalName(relativeFileNm)
	    IF InternalName '= "" 
        {
	        set sc = $$$OK
	        Set origNmSp =  $NAMESPACE
	        Set $NAMESPACE = nmSp
	        if ($F(InternalName, ".LOOKUP") > 0)
	        {
		        // Table name is between Namespace - first field and LOOKUP - last field
		        // Example: 
		        // Intername name: RESULTS.IHC.ITF.Process.Bpl.PowerPathReultsHl7To4Medica.Lookup.MedicaLocations.LOOKUP
		        // Table Name: IHC.ITF.Process.Bpl.PowerPathReultsHl7To4Medica.Lookup.MedicaLocations

		        // Strip namespace before first .
		        set tbNm = $E(InternalName, $F(InternalName,"."), *)
		        // String LOOKUP at the end
		        set tbNm = $E(tbNm, 1, ($F(tbNm,"LOOKUP") - 8))

		        Do ##class(IHC.ITF.ITFCOMMON.Utility).WriteToFile("Export lookup table: " _ tbNm _ " to " _ fileNm)
		        set sc = ##class(Ens.Util.LookupTable).%Export(fileNm, tbNm)
	        }
	        elseif ($F(InternalName, ".SYSDEF") > 0)
	        {
		        set prodNm = ##class(Ens.Director).GetActiveProductionName()
    			set sc = ##class(Ens.Config.DefaultSettings).%Export(fileNm, prodNm)
    			Do ##class(IHC.ITF.ITFCOMMON.Utility).WriteToFile("Export System defaults " _ prodNm _ " to " _ fileNm _ ", stat: " _ sc)
	        }
	        elseif ($F(InternalName, ".TASK") > 0)
	        {
		        // Strip namespace before first .
				set taskNm = $E(InternalName, $F(InternalName,"."), *)
				// String TASK at the end
				set taskNm = $E(taskNm, 1, ($F(taskNm,"TASK") - 6))
				Do ##class(IHC.ITF.ITFCOMMON.Utility).WriteToFile("Get task id for: " _ taskNm)
  				&sql(SELECT ID into idNum FROM %SYS.Task where Name = :taskNm)
     			IF (SQLCODE = 0)
				{
		 			set sc = ##class(%SYS.Task).ExportTasks($Lb(idNum), fileNm)

	    			Do ##class(IHC.ITF.ITFCOMMON.Utility).WriteToFile("Export Task " _ taskNm _ " to " _ fileNm _ ", stat: " _ sc)
	        	}
	        	else
	        	{
		        	set sc = $$$ERROR("SQL error: " _ SQLCODE)
		        	Do ##class(IHC.ITF.ITFCOMMON.Utility).WriteToFile( "Can not get task Id for " _ taskNm _ ", " _ sc)
	        	}
	        }
	        else {
	        	Set sc=$$Export^%occXMLExport(fileNm,"-d /diffexport",InternalName)
	        	Do ##class(IHC.ITF.ITFCOMMON.Utility).WriteToFile("occXMLExport: " _fileNm _ ", " _ InternalName _"Stat: " _sc)
	        }
	        Set $NAMESPACE = origNmSp
	        if ( ($$$ISOK(sc)) &&  (##class(%Library.File).Exists(fileNm)) )
	        {
	          set SelectedIntfiles = SelectedIntfiles _ "," _ InternalName
         	  Do ##class(IHC.ITF.ITFCOMMON.Utility).WriteToFile("CheckinFiles: " _ $NAMESPACE _ " " _ fileNm _" -d /diffexport " _InternalName)
	          Do ..AddToSvn(fileNm, 0, usrNm, passwd)

	        }
	        else
	        {
		          Do ##class(IHC.ITF.ITFCOMMON.Utility).WriteToFile("CheckinFiles: file does not exits: " _ fileNm _" -d /diffexport " _InternalName)

	        }
        }
	}

	if (files '= "" )
    {

	    Set cmd = $$$SVNCOMMIT _ " --username " _ usrNm _ " --password '" _ passwd  _ "' -m "" " _ comment _ " "" " _ files  ; a non-recursive commit (-N)
	    Set stat = ##class(IHC.ITF.SrcCtrlPkg.EnsembleSrcCtrlClass).ExecuteShellCmd( cmd)

        Do ##class(IHC.ITF.ITFCOMMON.Utility).WriteToFile("CheckinFiles: commit " _ files _ ", stat: " _ stat)

		if stat '= 0
		{
		  Do ##class(IHC.ITF.ITFCOMMON.Utility).WriteToFile("SVN commit error: " _ files)
		  Quit $$$ERROR($$$EnsErrGeneral, "SVN commit error")
		}

    }
    Do ..CreateListOfFilesInSvn(usrNm, nmSp )

     Quit $$$OK

	 Try {
		set stDtTm = $ZDATETIME($HOROLOG,3, 1)
        Set tRS = ##class(%ResultSet).%New("%SYS.Namespace:List")
        Set tSC = tRS.Execute()
        For {	       
            Quit:'tRS.Next()
            Set nmSp = tRS.Get("Nsp")   
            set nmSpData(nmSp) = nmSp	       
         }
         Do tRS.Close()
       		SET key=$ORDER(nmSpData(""))
       		set num = 0
   			WHILE (key'="") {

     			// Get next subscript 
     			SET key = $ORDER(nmSpData(key))
     			try {
      				SET $NAMESPACE = key
					Do ..UpdateAllEnsembleItems(key)
					set num = num + 1
     			} catch
     			{
	     			SET $NAMESPACE = "ITFCOMMON"
	     			Do ##class(IHC.ITF.ITFCOMMON.Utility).WriteToFile("Exception in change of namespace: " _ key)
     			}
     			Do ##class(IHC.ITF.ITFCOMMON.Utility).WriteToFile("UpdateAllNamespaces: Updated class information in " _ num _ " namespaces")

   			}
	 		set endDtTm = $ZDATETIME($HOROLOG,3, 1)
         	Do ..UpdateProcessTime("Ensemble update", stDtTm, endDtTm)	
    }
    Catch (ex) {
	    SET $NAMESPACE = "ITFCOMMON"
        Do ##class(IHC.ITF.ITFCOMMON.Utility).WriteToFile("Exception in reading namesapce: " _ $NAMESPACE _ ": " _ex.Name _ ", " _  ex.Code _ ", " _ ex.Data _ ", " _ ex.Location)
    }

	 NEW $NAMESPACE
      	 SET $NAMESPACE = nmSp
	set itNum = 0
	set prodNm = ##class(Ens.Director).GetActiveProductionName()
	  Set tProduction = ##class(Ens.Config.Production).%OpenId(prodNm,,.tSC)
	  Do ##class(IHC.ITF.ITFCOMMON.Utility).WriteToFile("GetItemsFromProduction from " _ prodNm _ " # items: " _ tProduction.Items.Count())
	  For i=1:1:tProduction.Items.Count() {
	   Set compItem = tProduction.Items.GetAt(i)
	   Set tItemName=compItem.Name, tBusinessType=compItem.BusinessType()
	   // Do ##class(IHC.ITF.ITFCOMMON.Utility).WriteToFile("GetItemsFromProduction: " _ tItemName)

	   Set tProduction = compItem.Production
	   Set:(tItemName '[ "||") tItemName = prodNm_"||"_tItemName
	    try
	    {
	  	 	Set configItem = ##class(Ens.Config.Production).OpenItemByConfigName(tItemName)

	   		If ' $IsObject(configItem)
 			{
	 			Do ##class(IHC.ITF.ITFCOMMON.Utility).WriteToFile("Not a object: " _ tItemName)
				Continue
 			}
 			// Open production and get items for the component
 			set tProjectArray = ""
 			kill tProjectArray
 			Set tSC=tProduction.getProjectArrayFromConfigItem(configItem,.tProjectArray) 
 		} catch err
	    {
		    Do ##class(IHC.ITF.ITFCOMMON.Utility).WriteToFile("Not a object: " _ tItemName)
			Continue
	    }
  		if $$$ISERR(tSC)
  		{
	  	 Do ##class(IHC.ITF.ITFCOMMON.Utility).WriteToFile("getProjectArrayFromConfigItem " _ tSC)	
	  	 QUIT
  		}
  		Set tSC=tProduction.expandProjectArray(.tProjectArray)  Quit:$$$ISERR(tSC)
  		#dim tProject as %Studio.Project
 		set tSC = tProduction.createStudioProjectFromArray(.tProject,.tProjectArray, "TEST", "DESC")
 		if $$$ISERR(tSC)
 		{
	 		 Do ##class(IHC.ITF.ITFCOMMON.Utility).WriteToFile("createStudioProjectFromArray " _ tSC)	
	  	 QUIT
 		}

 		Set k="" 
 		Do ##class(IHC.ITF.ITFCOMMON.Utility).WriteToFile(i _ " of " _ tProduction.Items.Count() _ ", project items in " _ tItemName _ " : " _ tProject.Items.Count())
 		For 
  		{ 
	   		#dim tItem As %Studio.ProjectItem 
			Set tItem=tProject.Items.GetNext(.k)  Quit:""=k||'$IsObject(tItem)
			Set tItemName=tItem.Name
			// Do ##class(IHC.ITF.ITFCOMMON.Utility).WriteToFile("ProjectItem: " _ tItemName)
		    if (tItemName '[ "HL7")
	   		{
		   		// Do ##class(IHC.ITF.ITFCOMMON.Utility).WriteToFile("ProjectItem not HL7: " _ tItemName)
		   		continue
	   		} 	
			if ('(tItemName [ "ITFCOMMON"))
			{

			// Does the Name end with type
			if $F(tItemName, tItem.Type) >  $L(tItemName)
			{
				set item = tItemName
	 		}
	 		else
	 		{
				set item = tItemName _ "." _ tItem.Type
	 		}


	              Do ##class(IHC.ITF.ITFCOMMON.Utility).WriteToFile("Add Item in "_ tItemName _ ": " _ item)
	              set stat =  ..AddToSourceControl(item, nmSp)	
	              if ( stat '= $$$OK)
	              {
		              Do ##class(IHC.ITF.ITFCOMMON.Utility).WriteToFile("GetItems: AddToSourceControl returned error")
	                return 0
	              }
	              set itNum = itNum + 1


           	 }
        }
   	 }
   	 return itNum

	 NEW $NAMESPACE
      	 SET $NAMESPACE = nmSp
	#dim tStat as %Status
	set itNum = 0

	Do ##class(IHC.ITF.ITFCOMMON.Utility).WriteToFile("GetItemsFromDictionary for " _ srcStr _ " in " _ $NAMESPACE)


     set stat = ##class(%SYSTEM.OBJ).GetPackageList(.lst, srcStr)		

    Do ##class(IHC.ITF.ITFCOMMON.Utility).WriteToFile("GetItemsFromDictionary: GetPackageList - " _ stat _ ", Data: " _  $DATA(lst))

   set clNm = ""
   FOR  {
     SET clNm=$ORDER(lst(clNm)) 
     QUIT:clNm=""
		           if ( (filter = 1) && ( ( clNm [ "SrcCtrlPkg") ||  (clNm [ "ITFCOMMON")) )
		           {
			           continue
		           }

		                 Do ##class(IHC.ITF.ITFCOMMON.Utility).WriteToFile("GetItemsFromDictionary: " _ clNm)


	              		set stat =  ..AddToSourceControl(clNm _ ".CLS", nmSp)	
	              		if ( stat '= $$$OK)
	              		{
		              		Do ##class(IHC.ITF.ITFCOMMON.Utility).WriteToFile("GetItemsFromDictionary: AddToSourceControl returned error: " _ clNm )
	                		return 0
	              		}
	              		set itNum = itNum  + 1


   		}
    	return itNum

	#dim tStat as %Status
	set itNum = 0
	 NEW $NAMESPACE
      	 SET $NAMESPACE = nmSp
	// Ignore classes that start with Intersystem class name	
    Set classesList=$LB("CSPX", "Ens", "EnsLib", "EnsPortal", "HS")

	// MAC and INC files
    Set result = ##class(%ResultSet).%New("%Library.Routine:RoutineList")
    Do result.Execute()


	While (result.Next()) {
	     set clNm =  result.Data("Name")
	     // Do ##class(IHC.ITF.ITFCOMMON.Utility).WriteToFile("%Library.Routine:RoutineList " _clNm _ " " _ $NAMESPACE)

	     if ( (clNm [ $NAMESPACE) || ($ZCVT(clNm, "U") [ ".INC") || ($ZCVT(clNm, "U") [".MAC"))
	     {

	       set clType = $PIECE(result.Data("Name"), ".", 1)

           if (' $LF(classesList, clType))       
           {

	         Set routine = ##class(%Routine).%New(clNm)
	         if ((' routine.Generated) && ($E(clNm,1,3) '= "Ens") )
	         {

	             Do ##class(IHC.ITF.ITFCOMMON.Utility).WriteToFile("Routine:GetIncAndRoutines: " _ clNm )
	              set stat =  ..AddToSourceControl(clNm, nmSp)	
	              if ( stat '= $$$OK)
	              {
		              Do ##class(IHC.ITF.ITFCOMMON.Utility).WriteToFile("GetIncAndRoutines: AddToSourceControl returned error")
	                return 0
	              }

	              set itNum = itNum + 1
	         }
           }
	   }
    }
    return itNum

set itmNum = 0 NEW $NAMESPACE SET $NAMESPACE = nmSp kill ^|"ITFCOMMON"|ItfSourceCtrl &sql(Declare CT Cursor for SELECT Name into tsk FROM %SYS.Task) Set SQLCODE=0 &sql(OPEN CT)
WHILE(SQLCODE = 0) { &sql(FETCH CT) Quit:SQLCODE set intNm = $NAMESPACE _ "." _ tsk _ ".TASK" Do ##class(IHC.ITF.ITFCOMMON.Utility).WriteToFile("GetTasks " _ intNm _ " in namespace: " _ $NAMESPACE) set stat = ..AddToSourceControl(intNm, nmSp, 0) if ( stat '= $$$OK) { Do ##class(IHC.ITF.ITFCOMMON.Utility).WriteToFile("AddToSourceControl in GetTasks returned error " _ stat) return 0 }
set itmNum = itmNum + 1
}
&sql(CLOSE CT) return itmNum


	Set svnFile = ..RelativeFileName(InternalName)
	// Write !, InternalName _ ": " _ svnFile
	if (getIntTime = 1)
		{
			set intTime= ##class(%RoutineMgr).TS(InternalName)
		}
		else
		{
			set intTime=""
		}
		NEW $NAMESPACE
  		SET $NAMESPACE = "ITFCOMMON"
		if (svnFile '= "")
	        {

   	        	&sql(UPDATE IHC_ITF_SrcCtrlPkg.ClassInfo 
   	        	SET InternalName = :InternalName, ClassModifiedTime=:intTime
   	        	WHERE FileName=:svnFile and Namespace = :nmSp )
   	        	// Write !, "SQL: " _ SQLCODE 
				if SQLCODE '= 0 {
					&sql(UPDATE IHC_ITF_SrcCtrlPkg.ClassInfo 
   	        		SET InternalName = :InternalName, ClassModifiedTime=:intTime, Namespace = :nmSp
   	        		WHERE FileName=:svnFile and  Namespace is NULL)
				}
				if SQLCODE '= 0 {
					// Write !, file _ " not found, Insert"
					&sql(INSERT INTO IHC_ITF_SrcCtrlPkg.ClassInfo (InternalName, FileName, Namespace, ClassModifiedTime)
					values (:InternalName, :svnFile, :nmSp, :intTime))
	  				if SQLCODE '= 0 {
		  				Do ##class(IHC.ITF.ITFCOMMON.Utility).WriteToFile("Insert to ClassInfo failed for " _ InternalName _ ", " _ svnFile _ ", " _nmSp)
		  				return 0
	  				}
				}
	        }
	return 1

// Set usrNm = $username
set stat = $$$ERROR(9100, "Could not add")
SET fullPath = $$$USRBASEDIR _ usrNm _ $$$SVNSRCTRUNK
set svnPath=$REPLACE(fName, fullPath, "")
Do ##class(IHC.ITF.ITFCOMMON.Utility).WriteToFile("AddDirectoriesToSvn " _ fullPath _ " = " _svnPath) 
SET fileParts = $Length(svnPath, "/")
// Check if directories from SVN BASE exists or not
FOR ind=1:1:fileParts - 1
{
	set dirName = $PIECE(svnPath, "/", ind)
	set fullPath = fullPath _ "/" _ dirName
	if ( ' ##class(%Library.File).Exists(fullPath))
	{
		Do ##class(IHC.ITF.ITFCOMMON.Utility).WriteToFile("AddDirectoriesToSvn, create directory: " _fullPath)
		Do ##class(%File).CreateDirectory(fullPath)
	}
	Do ..AddToSvn(fullPath, 1, usrNm, passwd)
}

NEW $NAMESPACE SET $NAMESPACE = "ITFCOMMON" &sql(UPDATE IHC_ITF_SrcCtrlPkg.SrcCtrlProcessLog SET StartTime=:stTm, EndTime =:endTm WHERE ProcessName = :nm )
if SQLCODE '= 0 {
&sql(INSERT INTO IHC_ITF_SrcCtrlPkg.SrcCtrlProcessLog (ProcessName, StartTime, EndTime) values (:nm, :stTm, :endTm)) if SQLCODE '= 0 { Do ##class(IHC.ITF.ITFCOMMON.Utility).WriteToFile("Insert to SrcCtrlProcessLog failed for " _ nm ) return 0 } }

	set fileInfo = ""
	Set fileObj=##class(%Library.File).%New(TempFile)
         set fileOpen = fileObj.Open("RS") ; Read mode and as stream
         // Do ##class(IHC.ITF.ITFCOMMON.Utility).WriteToFile("OPEN: " _ fileOpen)
         While 'fileObj.AtEnd 
         {
	         set readStr = fileObj.ReadLine(1000, .sc, .stat)
	         if ($L(readStr) > 0)
	         {
	        	set fileInfo = fileInfo _ ..HTMLEncode(readStr) _ "<BR>"
	         }	       
         }
         Do fileObj.Close()
         if (delete)
         {
           Do ##class(%Library.File).Delete(TempFile)
         }
         Do ##class(IHC.ITF.ITFCOMMON.Utility).WriteToFile(TempFile _ " length: " _ $LENGTH(fileInfo))
         Quit fileInfo


	 set svnBaseDir = $$$USRBASEDIR _ usrNm
 	 set tSC = ..createSvnDirectories(svnBaseDir)
 	 if $$$ISERR(tSC)
 	 {
	 	  Quit tSC
 	 }
     // Checkout complete source tree
     SET svnSrcTrunk = svnBaseDir _ $$$SVNSRCTRUNK
     Do ##class(IHC.ITF.ITFCOMMON.Utility).WriteToFile("Check if source control directory: " _ svnSrcTrunk)
     IF ' ##class(%File).DirectoryExists(svnSrcTrunk)
	 {
	   Do ##class(%File).CreateDirectoryChain(svnSrcTrunk)
	 }
	 set fullPath = svnSrcTrunk _ "cls" // cls directory should exists when checkout is successful
	 IF ' ##class(%File).DirectoryExists(fullPath)
	 {
	   set svnCmd = $$$SVNCHECKOUT _ " --username " _ usrNm _ " --password '" _ passwd _ "' " _ $$$SVNSRCURL _ " " _ svnSrcTrunk 
	   Set status = ##class(IHC.ITF.SrcCtrlPkg.EnsembleSrcCtrlClass).ExecuteShellCmd( svnCmd)
	   if (status '= 0)
		{
			set tSC = $$$ERROR($$$GeneralError, $$$SVNCHECKOUT _  " failed for user: " _ usrNm _ ", SVN URL:" _ $$$SVNSRCURL)
			Quit tSC
		}
	   Do ##class(IHC.ITF.ITFCOMMON.Utility).WriteToFile($$$SVNCHECKOUT _ " of " _ $$$SVNSRCURL _ "stat: " _ status)
	 }
	 set svnCmd = $$$SVNUPDATEALL _ " --username " _ usrNm _ " --password '" _ passwd _ "' " _ $$$SVNSRCURL _ " " _ svnSrcTrunk 

	 Set status = ##class(IHC.ITF.SrcCtrlPkg.EnsembleSrcCtrlClass).ExecuteShellCmd( svnCmd)
	 Do ##class(IHC.ITF.ITFCOMMON.Utility).WriteToFile($$$SVNUPDATEALL _ " " _ svnSrcTrunk _ ", stat: " _ status)

	 // Release files
	 set svnBaseDir = $$$USRRELEASEBASEDIR  _ usrNm
	 set tSC = ..createSvnDirectories(svnBaseDir)
	 Set svnRelTrunk = svnBaseDir _ $$$SVNSRCTRUNK
	 set fullPath = svnRelTrunk _ ".svn" // .svn directory should exists when checkout is successful
	 IF ' ##class(%File).DirectoryExists(fullPath)
	 {
	   Do ##class(%File).CreateDirectory(svnRelTrunk)
	   set svnCmd = $$$SVNCHECKOUT _ " --username " _ usrNm _ " --password '" _ passwd _ "'  " _ $$$SVNRELEASEURL _ " " _ svnRelTrunk 
	   Set status = ##class(IHC.ITF.SrcCtrlPkg.EnsembleSrcCtrlClass).ExecuteShellCmd( svnCmd)
	   if (status '= 0)
		{
			Do ##class(IHC.ITF.ITFCOMMON.Utility).WriteToFile($$$SVNCHECKOUT _ " failed for " _ $$$SVNRELEASEURL)
			set tSC = $$$ERROR($$$GeneralError, $$$SVNCHECKOUT _ " failed for user: " _ usrNm _ ", SVN URL:" _ $$$SVNRELEASEURL)
			Quit tSC
		}
	   Do ##class(IHC.ITF.ITFCOMMON.Utility).WriteToFile($$$SVNCHECKOUT _ " " _ $$$SVNRELEASEURL _ " " _ svnRelTrunk _ " " _ status)
	 }
	  set svnCmd = $$$SVNUPDATEALL _ " --username " _ usrNm _ " --password '" _ passwd _ "' " _ svnRelTrunk 
	  Set status = ##class(IHC.ITF.SrcCtrlPkg.EnsembleSrcCtrlClass).ExecuteShellCmd( svnCmd)
	  Do ##class(IHC.ITF.ITFCOMMON.Utility).WriteToFile($$$SVNUPDATEALL _ " of " _ svnRelTrunk _ ", stat: " _ status)

	 Do ##class(IHC.ITF.ITFCOMMON.Utility).WriteToFile("CheckSvnSetup: OK ")
     Quit $$$OK

	 // check for the parent directory


	 IF ' ##class(%File).DirectoryExists(usrBaseDir)
	 {
		 Do ##class(IHC.ITF.ITFCOMMON.Utility).WriteToFile("createSvnDirectories: " _ " Create User Home directory: " _ usrBaseDir)
		 if $$$ISERR( ##class(%File).CreateDirectoryChain(usrBaseDir))
		    Quit $$$ERROR(100, "User Home directory could not be created: " _usrBaseDir)
     }


     SET svnBaseDir = usrBaseDir _ $$$SVNSRCTRUNK
	 IF ' ##class(%File).DirectoryExists(svnBaseDir)
     {
   	     Do ##class(IHC.ITF.ITFCOMMON.Utility).WriteToFile("createSvnDirectories: Create " _ svnBaseDir )

         Do ##class(%File).CreateDirectoryChain(svnBaseDir)

	 }

     IF ' ##class(%File).DirectoryExists(svnBaseDir)
     {
	     Quit $$$ERROR(100, "User SVN directory could not be created: " _ svnBaseDir)
     }
     Quit $$$OK

// Write !, "Mapping Name"
// Do ##class(IHC.ITF.ITFCOMMON.Utility).WriteToFile("Name: " _ InternalName)
If $data(^|"ITFCOMMON"|ItfSourceCtrl)'=11 
{
	Set src = ..setSources()
	// Write !,"^|""ITFCOMMON""|ItfSourceCtrl is not setup so hooks will not work"
	Set src = $data(^|"ITFCOMMON"|ItfSourceCtrl) 
	Do ##class(IHC.ITF.ITFCOMMON.Utility).WriteToFile( "Sources set: " _ src)
}	
If $data(^|"ITFCOMMON"|ItfSourceCtrl)'=11 
{
	Do ##class(IHC.ITF.ITFCOMMON.Utility).WriteToFile("^|""ITFCOMMON""|ItfSourceCtrl is not setup so hooks will not work" )
	Quit ""
}
// For an abstract document, use the GetOther() method to try to determine its "real" class
If ##class(%RoutineMgr).UserType(InternalName,.docclass,.doctype) {
	// Check for a real abstract document subclass (or GetOther() may not work)
	If $classmethod(docclass,"%IsA","%Studio.AbstractDocument") {
		// Grab the actual name
		Set actualName = $classmethod(docclass,"GetOther",InternalName)
		// The actualName is only valid if we get a single .cls as a result
		If actualName'[",",$ZCVT($P(actualName,".",$L(actualName,".")),"U")="CLS" {
			// We use what GetOther() gives us, thus Demo.Loan.FindRateProcess.bpl becomes Demo.Loan.FindRateProcess.cls
			Set InternalName = actualName
		}
	}
}	
// Write !, "InternalName: " _ InternalName
If $$CheckProtect^%qccServer(InternalName) Quit ""
Set nam=$p(InternalName,".",1,$l(InternalName,".")-1),ext=$p(InternalName,".",$l(InternalName,".")),ext=$zcvt(ext,"u")
If nam="" Quit ""
If ext="PRJ",nam["Default_" Quit ""
If ext="CLS",$$$defClassKeyGet(nam,$$$cCLASSgeneratedby)'="" Quit ""
Set default=0
// Write !, "ext: " _ ext _ " / " _ nam
Set p=$order(^|"ITFCOMMON"|ItfSourceCtrl(ext,nam)) For  s p=$order(^|"ITFCOMMON"|ItfSourceCtrl(ext,p),-1) Quit:p=""  If $extract(nam,1,$length(p))=p,$data(^|"ITFCOMMON"|ItfSourceCtrl(ext,p),found) Quit
If $data(found)=0,$data(^|"ITFCOMMON"|ItfSourceCtrl(ext,"*"),found) Set default=1
If $data(found)=0 Quit ""
// Write !, "found: " _ found
If InternalName["/" {
	Set InternalName=$extract(InternalName,$length(p)+1,*)
	Set extNm = $translate(found_$translate(InternalName,"%","_"),"\","/")
	Quit extNm
}
If ext="CLS"||(ext="PRJ")||(##class(%RoutineMgr).UserType(InternalName))
{ 
   set extNm = $translate(found_$translate(nam,".%","/")_".xml","\","/")
   Quit extNm
}
set extNm = $translate($g(found)_$tr(nam,"%"_$s(default:".",1:""),"_/")_".xml","\","/")
// Write !, "extNm: " _ extNm
Quit extNm


	SET delim=" "
   		SET countdown=$LENGTH(cmd,delim)
   		SET countup=2
   		SET arrInd=1
   		SET cmdArr(1) = ""
   		set multiWord = 0
   		Set linuxCmd = $PIECE(cmd,delim,1)
   		Do ##class(IHC.ITF.ITFCOMMON.Utility).WriteToFile($ZDATETIME($HOROLOG) _ " EnsembleSrcCtrlClass.ExecuteShellCmd: " _ linuxCmd )
   		FOR reps=countdown:-1:1 {
      		SET extract=$PIECE(cmd,delim,countup)
           	if ( ($L(extract) '= 0) && (extract '= " ") ) {
	           	if ( (extract = """") && (multiWord = 0) )
	           	{
		           	set multiWord = 1
		           	SET countup = countup+1
		           	SET cmdArr(arrInd) = ""
		           	CONTINUE 
	           	}
	           	elseif ( (extract = """") && (multiWord = 1) )
	           	{
		           	set multiWord = 0
		           	Do ##class(IHC.ITF.ITFCOMMON.Utility).WriteToFile("Multi words: " _ cmdArr(arrInd))
		           	Set arrInd = arrInd + 1
		           	SET countup = countup+1
		           	CONTINUE 
	           	}
	           	if (multiWord = 1)
	           	{
		           	if ($L(cmdArr(arrInd)) = 0)
		           	{
			           	SET cmdArr(arrInd) = extract
		           	}
		           	else
		           	{
		           		SET cmdArr(arrInd) = cmdArr(arrInd) _ " " _ extract
		           	}
	           	}
	           	else
	           	{
      				SET cmdArr(arrInd) = extract
      				Do ##class(IHC.ITF.ITFCOMMON.Utility).WriteToFile("Array: (" _ arrInd _ "): " _ cmdArr(arrInd))
      				Set arrInd = arrInd + 1
	           	}
      		}
      		SET countup = countup+1
   		}

        set stat = $ZF(-100,"/SHELL", linuxCmd, .cmdArr)
        return stat
